parameters.code:
// Normaliza o payload vindo da Evolution API
const body = $json || {};
const data = body.data || body;
const key = data.key || {};

const rawEvent = body.event || data.event || body.type || '';
const event = String(rawEvent).toUpperCase().replace('.', '_');
const remoteJid = key.remoteJid || data.from || body.from || '';
const isGroup = typeof remoteJid === 'string' && remoteJid.includes('@g.us');
const fromMe = key.fromMe === true || data.fromMe === true;
const msg = data.message || {};

// Detecta mídias específicas no payload da Evolution API / Baileys
const isImage = !!(msg.imageMessage || msg.ephemeralMessage?.message?.imageMessage || data.messageType === 'imageMessage');
const isDocument = !!(msg.documentMessage || msg.ephemeralMessage?.message?.documentMessage || data.messageType === 'documentMessage');
const isAudio = !!(msg.audioMessage || msg.ephemeralMessage?.message?.audioMessage || data.messageType === 'audioMessage');
const isVideo = !!(msg.videoMessage || msg.ephemeralMessage?.message?.videoMessage || data.messageType === 'videoMessage');
const isSticker = !!(msg.stickerMessage || msg.ephemeralMessage?.message?.stickerMessage || data.messageType === 'stickerMessage');
const isMedia = isImage || isDocument || isAudio || isVideo || isSticker;

let textRaw = msg.conversation || msg.extendedTextMessage?.text || msg.ephemeralMessage?.message?.conversation || msg.ephemeralMessage?.message?.extendedTextMessage?.text || data.text || '';

if (!textRaw && isMedia) {
  if (isImage) textRaw = '[Imagem]';
  else if (isDocument) textRaw = '[Documento/PDF]';
  else if (isAudio) textRaw = '[Áudio]';
  else if (isVideo) textRaw = '[Vídeo]';
  else if (isSticker) textRaw = '[Sticker]';
  else textRaw = '[Mídia]';
}

const text = String(textRaw || '').trim();
const phone = String(remoteJid || '').replace(/@.*$/, '').replace(/\D/g, '');
const instance = body.instance?.instanceName || body.instance?.name || body.instanceName || data.instanceName || body.instance || 'teste-atendimento';

const shouldProcess = event === 'MESSAGES_UPSERT'
  && !isGroup
  && phone !== ''
  && text !== ''
  && !fromMe;

return [{ 
  json: {
    event,
    from: remoteJid || data.from || body.from || 'unknown',
    text,
    text_raw: text,
    phone,
    isGroup,
    fromMe,
    is_self_test: false,
    should_process: shouldProcess,
    is_media: isMedia,
    is_image: isImage,
    is_document: isDocument,
    instance,
    raw: body
  }
}];

